android.extraProguardRules:
# ML Kit / Firebase components are created by reflection (no-arg constructors).
-keep class * implements com.google.firebase.components.ComponentRegistrar { public <init>(); }
-keep class com.google.mlkit.** { *; }
# MediaPipe tasks: JNI entry points and protobuf-lite messages.
-keep class com.google.mediapipe.** { *; }
-keep class com.google.protobuf.** { *; }
# Flogger (used by MediaPipe) finds its caller by class name on the stack.
-keep class com.google.common.flogger.** { *; }
-dontwarn com.google.mediapipe.**
-dontwarn javax.lang.model.**
